// Synthetic replica of react-native-safe-area-context@4 sources: TSX shipped as
// the "react-native" entry. This models the pure-JS surface of the library
// (insets fallback + provider) with no native module access, so a bundler build
// fully reproduces its build-time behavior.
import { Fragment } from "react";

export type EdgeInsets = {
  top: number;
  right: number;
  bottom: number;
  left: number;
};

export const SAFE_AREA_OK = "SAFE_AREA_OK";

const FALLBACK_INSETS: EdgeInsets = { top: 0, right: 0, bottom: 0, left: 0 };

let currentInsets: EdgeInsets = FALLBACK_INSETS;

export function getSafeAreaInsets(): EdgeInsets {
  return currentInsets;
}

export function SafeAreaProvider(props: { initialMetrics?: { insets: EdgeInsets }; children?: unknown }) {
  if (props.initialMetrics) {
    currentInsets = props.initialMetrics.insets;
  }
  return <Fragment>{props.children}</Fragment>;
}

export function SafeAreaView(props: { children?: unknown }) {
  return <Fragment>{props.children}</Fragment>;
}
